'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var strided = require( '@stdlib/blas/ext/base/cfill' ).ndarray;
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );


// MAIN //

/**
* Fills a complex single-precision floating-point ndarray with a specified scalar constant.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing a single one-dimensional input ndarray and a zero-dimensional ndarray containing a scalar constant
* @returns {complex64ndarray} input ndarray
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
* var ndarray2array = require( '@stdlib/ndarray/to-array' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
*
* var buffer = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var x = new ndarray( 'complex64', buffer, [ 2 ], [ 1 ], 0, 'row-major' );
*
* var alpha = scalar2ndarray( new Complex64( 10.0, 10.0 ), {
*     'dtype': 'complex64'
* });
*
* var out = cfill( [ x, alpha ] );
* // returns <ndarray>
*
* var arr = ndarray2array( out );
* // returns [ <Complex64>[ 10.0, 10.0 ], <Complex64>[ 10.0, 10.0 ] ]
*/
function cfill( arrays ) {
	var alpha;
	var buf;
	var sx;
	var ox;
	var x;
	var N;

	x = arrays[ 0 ];
	alpha = ndarraylike2scalar( arrays[ 1 ] );

	N = numelDimension( x, 0 );
	if ( N <= 0 ) {
		return x;
	}
	buf = getData( x );
	sx = getStride( x, 0 );
	ox = getOffset( x );

	strided( N, alpha, buf, sx, ox );
	return x;
}


// EXPORTS //

module.exports = cfill;
